                      socInfoString_(socInfoString),
                      compileInfo_(compileInfo),
                      coreNum_(coreNum),
                      ubSize_(ubSize),
                      tilingDataSize_(tilingDataSize) {}

    TilingContextPara(const std::string& opName,
                      const std::vector<TensorDescription>& inputTensorDesc,
