    uint64_t ubSize_         = 262144;
    uint64_t tilingDataSize_ = 4096;
    void* compileInfo_ = nullptr;
    std::string socVersion_;
    std::string socInfoString_;
    int32_t deterministicInfo_ = 0;
};

