/*!
 * \file ai_infra_aggregate_hidden_tiling.h
 * \brief
 */

#ifndef AGGREGATE_HIDDEN_TILING_H_
#define AGGREGATE_HIDDEN_TILING_H_

#define AGGREGATE_HIDDEN_BF16 0 
#define AGGREGATE_HIDDEN_HALF 1 

#include "exe_graph/runtime/tiling_context.h"
#include "tiling/platform/platform_ascendc.h"
#include "register/op_def_registry.h"
#include "register/tilingdata_base.h"
#include "tiling/tiling_api.h"
#include "platform/platform_info.h"

namespace optiling {
// ------------------公共定义--------------------------
struct TilingRequiredParaInfo {
    const gert::CompileTimeTensorDesc *desc;
    const gert::StorageShape *shape;
};

struct TilingOptionalParaInfo {
    const gert::CompileTimeTensorDesc *desc;
    const gert::Tensor *tensor;
    const gert::StorageShape *shape;
};

// -----------算子TilingData定义---------------
BEGIN_TILING_DATA_DEF(AiInfraAggregateHiddenTilingData)
TILING_DATA_FIELD_DEF(uint8_t, ifMask);
TILING_DATA_FIELD_DEF(int64_t, hSize);
TILING_DATA_FIELD_DEF(int64_t, bSize);
TILING_DATA_FIELD_DEF(int64_t, sSize);
TILING_DATA_FIELD_DEF(int64_t, baseH);
TILING_DATA_FIELD_DEF(int64_t, baseB);
TILING_DATA_FIELD_DEF(int64_t, baseS);
TILING_DATA_FIELD_DEF(int64_t, baseHTail);
TILING_DATA_FIELD_DEF(int64_t, baseBTail);
TILING_DATA_FIELD_DEF(int64_t, baseSTail);
TILING_DATA_FIELD_DEF(int64_t, baseHCnt);
TILING_DATA_FIELD_DEF(int64_t, baseBCnt);
TILING_DATA_FIELD_DEF(int64_t, baseSCnt);
END_TILING_DATA_DEF;

REGISTER_TILING_DATA_CLASS(AiInfraAggregateHidden, AiInfraAggregateHiddenTilingData)

// -----------算子CompileInfo定义-------------------
struct AiInfraAggregateHiddenCompileInfo {};

// -----------算子Tiling入参结构体定义---------------
struct AhParaInfo {
    TilingRequiredParaInfo input = {nullptr, nullptr};
    TilingRequiredParaInfo weight = {nullptr, nullptr};
    TilingOptionalParaInfo mask = {nullptr, nullptr};
    TilingRequiredParaInfo output = {nullptr, nullptr};
};

// -----------算子Tiling入参信息类---------------
class AHTilingInfo {
public:
    const char *opName = nullptr;
    fe::PlatFormInfos *platformInfo = nullptr;
    AhParaInfo opParamInfo;
    // Base Param
    platform_ascendc::SocVersion socVersion = platform_ascendc::SocVersion::ASCEND910_93;
    uint8_t ifMask = 0;
    int64_t hSize = 0;
    int64_t bSize = 0;
    int64_t sSize = 0;
    int64_t baseH = 0;
    int64_t baseB = 0;
    int64_t baseS = 0;
    int64_t baseHTail = 0;
    int64_t baseBTail = 0;
    int64_t baseSTail = 0;
    int64_t baseHCnt = 0;
    int64_t baseBCnt = 0;
    int64_t baseSCnt = 0;
    int64_t tilingKey = AGGREGATE_HIDDEN_BF16;
    int64_t blockDim = 0;
};

// -----------算子Tiling入参信息解析及Check类---------------
class AHInfoParser {
public:
    explicit AHInfoParser(gert::TilingContext *context) : context_(context)
    {
    }
    ~AHInfoParser() = default;

    ge::graphStatus GetOpName();
    ge::graphStatus GetNpuInfo();
    ge::graphStatus CheckInputValid();
    ge::graphStatus CheckWeightValid();
    ge::graphStatus CheckMaskValid();
    ge::graphStatus CheckOutputValid();
    ge::graphStatus GetTilingKey();
    ge::graphStatus CoreSplit();
    void GenerateInfo(AHTilingInfo &ahInfo);
    void DumpTilingInfo(AHTilingInfo &ahInfo);
    ge::graphStatus ParseAndCheck(AHTilingInfo &ahInfo);

public:
    gert::TilingContext *context_ = nullptr;
    const char *opName_;
    fe::PlatFormInfos *platformInfo_;
    AhParaInfo opParamInfo_;

    // BaseParams
    uint8_t ifMask_ = 0;
    int64_t hSize_ = 0;
    int64_t bSize_ = 0;
    int64_t sSize_ = 0;
    int64_t baseH_ = 0;
    int64_t baseB_ = 0;
    int64_t baseS_ = 0;
    int64_t baseHTail_ = 0;
    int64_t baseBTail_ = 0;
    int64_t baseSTail_ = 0;
    int64_t baseHCnt_ = 0;
    int64_t baseBCnt_ = 0;
    int64_t baseSCnt_ = 0;
    int64_t tilingKey_ = AGGREGATE_HIDDEN_BF16;
    int64_t aivNum_ = 0;
    int64_t blockDim_ = 0;

    platform_ascendc::SocVersion socVersion_ = platform_ascendc::SocVersion::ASCEND910_93;
    ge::DataType inputType_ = ge::DT_BF16;
    ge::DataType weightType_ = ge::DT_BF16;
    ge::DataType outputType_ = ge::DT_BF16;
};

// ---------------算子Tiling类---------------
class AiInfraAggregateHiddenTiling {
public:
    explicit AiInfraAggregateHiddenTiling(gert::TilingContext *context) : context_(context){};
    ge::graphStatus DoTiling(AHTilingInfo *tilingInfo);

private:
    gert::TilingContext *context_ = nullptr;
    AiInfraAggregateHiddenTilingData tilingData_;
};

} // namespace optiling
#endif // AGGREGATE_HIDDEN_TILING_H_

