static constexpr int64_t NUM_ZERO = 0;
static constexpr int64_t NUM_ONE = 1;
static constexpr int64_t NUM_TWO = 2;
static constexpr int64_t NUM_THREE = 3;
static constexpr int64_t NUM_FOUR = 4;
static constexpr int64_t NUM_FIVE = 5;
static constexpr int64_t NUM_SIX = 6;
static constexpr int64_t NUM_SEVEN = 7;
static constexpr int64_t NUM_EIGHT = 8;
static constexpr int64_t FOURTY = 40;
static constexpr int64_t FOURTY_EIGHT = 48;

// ------------------算子原型索引常量定义----------------
// Inputs Index
static constexpr int64_t INPUT_INDEX = 0;
static constexpr int64_t WEIGHT_INDEX = 1;
static constexpr int64_t MASK_INDEX = 2;

// Outputs Index
static constexpr int64_t OUTPUT_INDEXER = 0;

// Dim Num
static constexpr int64_t DIM_NUM_TWO = 2;
static constexpr int64_t DIM_NUM_THREE = 3;

// Dim Index
static constexpr int64_t DIM_IDX_ZERO = 0;
static constexpr int64_t DIM_IDX_ONE = 1;
static constexpr int64_t DIM_IDX_TWO = 2;
static constexpr int64_t DIM_IDX_THREE = 3;

// 入参限制常量
static constexpr int64_t S_SIZE_LIMIT = 32 * 1024;  // 32K
static constexpr int64_t B_SIZE_LIMIT = 8;
static constexpr int64_t H_SIZE_UP_LIMIT = 24576;  // 192*128
static constexpr int64_t H_SIZE_DOWN_LIMIT = 384;  // 192*2
static constexpr int64_t W_SIZE_LIMIT = 3;         // 卷积的窗口固定是3
static constexpr int64_t H_SIZE_FULL = 4096;       // UB全载时，H最大是4096

// workspace上预留100M
static constexpr int64_t DEFAULT_WORKSPACE_SIZE = 100 * 1024 * 1024;

// --------------------------AHInfoParser类成员函数定义-------------------------------------
ge::graphStatus AHInfoParser::GetOpName()
{
    if (context_->GetNodeName() == nullptr) {
        OP_LOGE("AiInfraAggregateHidden", "opName got from TilingContext is nullptr");
        return ge::GRAPH_FAILED;
    }
    opName_ = context_->GetNodeName();
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::GetNpuInfo()
{
    platformInfo_ = context_->GetPlatformInfo();
    OP_CHECK_IF(platformInfo_ == nullptr, OP_LOGE(opName_, "GetPlatformInfo is nullptr."), return ge::GRAPH_FAILED);

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo_);
    aivNum_ = static_cast<int64_t>(ascendcPlatform.GetCoreNumAiv());
    uint32_t aicNum = ascendcPlatform.GetCoreNumAic();
    OP_CHECK_IF(aicNum == 0 || aivNum_ == 0, OP_LOGE(opName_, "num of core obtained is 0."), return GRAPH_FAILED);
    socVersion_ = ascendcPlatform.GetSocVersion();
    if ((socVersion_ != platform_ascendc::SocVersion::ASCEND910B) &&
        (socVersion_ != platform_ascendc::SocVersion::ASCEND910_93)) {
        OP_LOGE(opName_, "SOC Version[%d] is not support.", (int32_t)socVersion_);
        return GRAPH_FAILED;
    }
    OP_CHECK_IF(context_->GetWorkspaceSizes(1) == nullptr,
        OP_LOGE(opName_, "workSpaceSize got from ge is nullptr"),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(context_->GetRawTilingData() == nullptr,
        OP_LOGE(context_->GetNodeName(), "RawTilingData got from GE context is nullptr."),
        return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::CheckInputValid()
{
    // 1.获取变量相关参数
    opParamInfo_.input.desc = context_->GetInputDesc(INPUT_INDEX);
    opParamInfo_.input.shape = context_->GetInputShape(INPUT_INDEX);
    // 2.检查变量是否存在
    OP_CHECK_IF(opParamInfo_.input.shape == nullptr,
        OP_LOGE(opName_, "Shape of tensor input is nullptr"),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(opParamInfo_.input.desc == nullptr,
        OP_LOGE(opName_, "Desc of tensor input is nullptr"),
        return ge::GRAPH_FAILED);
    // 3.检查变量类型
    inputType_ = opParamInfo_.input.desc->GetDataType();
    OP_CHECK_IF(((inputType_ != ge::DT_FLOAT16) && (inputType_ != ge::DT_BF16)),
        OP_LOGE(opName_, "The data types of the input must be float16 or bfloat16."),
        return ge::GRAPH_FAILED);
    // 4.检查变量Shape的Dim
    int64_t inputShapeDim = opParamInfo_.input.shape->GetStorageShape().GetDimNum();
    int64_t inputExpectShapeDim = DIM_NUM_THREE;
    OP_CHECK_IF(inputShapeDim != inputExpectShapeDim,
        OP_LOGE(
            opName_, "the dim num of input's shape should be %u, but now is %u", inputExpectShapeDim, inputShapeDim),
        return ge::GRAPH_FAILED);
    // 5.检查变量shape大小是否超限 input [S,B,H],
    //  -----------------------check S Size-------------------
    sSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO));
    OP_LOGI(context_->GetNodeName(), "sSize is %d", sSize_);
    OP_CHECK_IF(sSize_ > S_SIZE_LIMIT,
        OP_LOGE(opName_, "the max of S size only support 32K, but now is %d.", sSize_),
        return ge::GRAPH_FAILED);
    // -----------------------check B Size-------------------
    bSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE));
    OP_LOGI(context_->GetNodeName(), "bSize is %d", bSize_);
    OP_CHECK_IF(bSize_ > B_SIZE_LIMIT,
        OP_LOGE(opName_, "the max of batch size only support 8, but now is %d.", bSize_),
        return ge::GRAPH_FAILED);
    // -----------------------check H Size-------------------
    hSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO));
    OP_LOGI(context_->GetNodeName(), "hSize is %d", hSize_);
    OP_CHECK_IF(hSize_ > H_SIZE_UP_LIMIT,
        OP_LOGE(opName_, "the max of H size must smaller than 24576, but now is %d.", hSize_),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(hSize_ < H_SIZE_DOWN_LIMIT,
        OP_LOGE(opName_, "the min of H size must larger than 384, but now is %d.", hSize_),
        return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::CheckWeightValid()
{
    // 1.获取变量相关参数
    opParamInfo_.weight.desc = context_->GetInputDesc(WEIGHT_INDEX);
    opParamInfo_.weight.shape = context_->GetInputShape(WEIGHT_INDEX);
    // 2.检查变量是否存在
    OP_CHECK_IF(opParamInfo_.weight.shape == nullptr,
        OP_LOGE(opName_, "Shape of tensor weight is nullptr"),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(opParamInfo_.weight.desc == nullptr,
        OP_LOGE(opName_, "Desc of tensor weight is nullptr"),
        return ge::GRAPH_FAILED);
    // 3.检查变量类型
    weightType_ = opParamInfo_.weight.desc->GetDataType();
    OP_CHECK_IF((inputType_ != weightType_),
        OP_LOGE(opName_, "The data types of the input and weight must be the same."),
        return ge::GRAPH_FAILED);
    // 4. 检查变量Shape的Dim
    int64_t weightShapeDim = opParamInfo_.weight.shape->GetStorageShape().GetDimNum();
    int64_t weightExpectShapeDim = DIM_NUM_TWO;
    OP_CHECK_IF(weightShapeDim != weightExpectShapeDim,
        OP_LOGE(
            opName_, "the dim num of weight's shape should be %u, but now is %u", weightExpectShapeDim, weightShapeDim),
        return ge::GRAPH_FAILED);
    // 5.检查变量shape大小是否超限,weight [W=3,H]
    //  -----------------------check W Size-------------------
    OP_CHECK_IF((opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ZERO) != W_SIZE_LIMIT),
        OP_LOGE(opName_, "The window size of convolution must be 3."),
        return ge::GRAPH_FAILED);
    // 6.检查变量shape大小是否与input一致
    //  -----------------------check H Size-------------------
    OP_CHECK_IF((opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ONE) != hSize_),
        OP_LOGE(opName_,
            "Input dim 2 and Weight dim 1 is %u, %u respectively, they must be same.",
            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO),
            opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ONE)),
        return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::CheckMaskValid()
{
    // 1.获取变量相关参数
    opParamInfo_.mask.tensor = context_->GetOptionalInputTensor(MASK_INDEX);
    opParamInfo_.mask.desc = context_->GetOptionalInputDesc(MASK_INDEX);
    // 2.判断可选变量是否存在
    ifMask_ = 0;
    if (opParamInfo_.mask.tensor != nullptr) {
        ifMask_ = 1;
        // 3. 检查变量类型
        OP_CHECK_IF(opParamInfo_.mask.desc->GetDataType() != ge::DT_BOOL,
            OP_LOGE(opName_, "the mask data type only support BOOL"),
            return ge::GRAPH_FAILED);
        // 4. 检查变量Shape的Dim
        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDimNum() != DIM_NUM_TWO),
            OP_LOGE(opName_, "the dim num of mask's shape should be 2"),
            return ge::GRAPH_FAILED);
        // 5.检查变量shape大小是否与input一致,mask [B,S]
        //  -----------------------check B Size-------------------
        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ZERO) != bSize_),
            OP_LOGE(opName_,
                "Input dim 1 and mask dim 0 is %u, %u respectively, they must be same.",
                opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE),
                opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ZERO)),
            return ge::GRAPH_FAILED);
        // -----------------------check S Size-------------------
        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ONE) != sSize_),
            OP_LOGE(opName_,
                "Input dim 0 and mask dim 1 is %u, %u respectively, they must be same.",
                opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO),
                opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ONE)),
            return ge::GRAPH_FAILED);
    }

    return ge::GRAPH_SUCCESS;
}

