426	ge::graphStatus AiInfraAggregateHiddenTiling::DoTiling(AHTilingInfo *tilingInfo)
427	{
428	    // -------------set blockdim-----------------
429	    context_->SetBlockDim(static_cast<uint32_t>(tilingInfo->blockDim));
430	    // -------------set workspacesize-----------------
431	    size_t *workSpaces = context_->GetWorkspaceSizes(1);
