ge::graphStatus AHInfoParser::GetTilingKey()  // 根据输入数据的类型区分tiling key
{
    tilingKey_ = AGGREGATE_HIDDEN_BF16;
    if (inputType_ == ge::DT_FLOAT16) {
        tilingKey_ = AGGREGATE_HIDDEN_HALF;
    }
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::CoreSplit()  // 分核计算,如果H能全载就不切H
{
    baseHCnt_ = (hSize_ + H_SIZE_FULL - NUM_ONE) /
                H_SIZE_FULL;  // H切分的份数 = hSize_/4096取上整 baseHCnt_表示一整份H需要用几个核处理
    int64_t flagChange = NUM_ZERO;
    // 调整baseHCnt_使得它能整除aivNum_
    // aivNum_ == 48 | baseHCnt_ == 5
    if (aivNum_ == FOURTY_EIGHT && baseHCnt_ == NUM_FIVE) {
        baseHCnt_ = NUM_SIX;
        flagChange = NUM_ONE;
    }
    // conditions are independent
    // aivNum_ == 40 | baseHCnt_ == 6
    if (aivNum_ == FOURTY && baseHCnt_ == NUM_SIX) {
        baseHCnt_ = NUM_EIGHT;
        flagChange = NUM_ONE;
    }
    // aivNum_ == 40 | baseHCnt_ == 3
    if (aivNum_ == FOURTY && baseHCnt_ == NUM_THREE) {
        baseHCnt_ = NUM_FOUR;
        flagChange = NUM_ONE;
    }
    // else, no assignment

    // 计算baseH_
    if (hSize_ <= H_SIZE_FULL) {
        baseH_ = hSize_;
        baseHTail_ = baseH_;
    } else {
        baseH_ = H_SIZE_FULL;  // baseHCnt_没有被额外修改
        baseHTail_ = hSize_ % baseH_ == NUM_ZERO ? baseH_ : hSize_ % baseH_;
        if (flagChange == NUM_ONE) {  // baseHCnt_被额外修改
            baseH_ = hSize_ / baseHCnt_;
            baseHTail_ = hSize_ % baseHCnt_ == NUM_ZERO ? baseH_ : hSize_ - (baseH_ * (baseHCnt_ - NUM_ONE));
        }
    }

    // 计算baseB_
    int64_t coreNumH = aivNum_ / baseHCnt_;  // coreNumH 表示B还能切多少个核
    baseB_ = (bSize_ + coreNumH - NUM_ONE) / coreNumH;
    if (bSize_ % baseB_ == NUM_ZERO) {
        baseBTail_ = baseB_;
    } else {
        baseBTail_ = bSize_ % baseB_;
    }
    // 计算baseS_
    // 默认不切S
    baseS_ = sSize_;
    baseSTail_ = baseS_;
    baseSCnt_ = NUM_ONE;      // 1表示不切S
    if (baseB_ == NUM_ONE) {  // baseB_大于1，表示B没切完，不切S
        baseSCnt_ = coreNumH / bSize_;
        baseS_ = baseSCnt_ > sSize_ ? NUM_ONE : (sSize_ + baseSCnt_ - NUM_ONE) / baseSCnt_;
        baseSCnt_ = baseSCnt_ > sSize_ ? sSize_ : (sSize_ + baseS_ - 1) / baseS_;
        baseSTail_ = sSize_ % baseSCnt_ == NUM_ZERO ? baseS_ : sSize_ - (baseS_ * (baseSCnt_ - NUM_ONE));
    }

    // 计算blockDim
    baseBCnt_ = (bSize_ + baseB_ - NUM_ONE) / baseB_;
    blockDim_ = baseHCnt_ * baseBCnt_ * baseSCnt_;

    return ge::GRAPH_SUCCESS;
}

void AHInfoParser::GenerateInfo(AHTilingInfo &ahInfo)
{
    ahInfo.opName = opName_;
    ahInfo.platformInfo = platformInfo_;
    ahInfo.opParamInfo = opParamInfo_;
    ahInfo.socVersion = socVersion_;

    ahInfo.ifMask = ifMask_;
    ahInfo.sSize = sSize_;
    ahInfo.bSize = bSize_;
    ahInfo.hSize = hSize_;
    ahInfo.baseS = baseS_;
    ahInfo.baseB = baseB_;
    ahInfo.baseH = baseH_;
    ahInfo.baseSTail = baseSTail_;
    ahInfo.baseBTail = baseBTail_;
    ahInfo.baseHTail = baseHTail_;
    ahInfo.baseSCnt = baseSCnt_;
    ahInfo.baseBCnt = baseBCnt_;
    ahInfo.baseHCnt = baseHCnt_;
    ahInfo.tilingKey = tilingKey_;
    ahInfo.blockDim = blockDim_;
}

void AHInfoParser::DumpTilingInfo(AHTilingInfo &ahInfo)
{
    OP_LOGD(context_->GetNodeName(), "seqLength:  %ld", ahInfo.sSize);
    OP_LOGD(context_->GetNodeName(), "batchSize:  %ld", ahInfo.bSize);
    OP_LOGD(context_->GetNodeName(), "hiddenSize:  %ld", ahInfo.hSize);
    OP_LOGD(context_->GetNodeName(), "baseH:  %ld", ahInfo.baseH);
    OP_LOGD(context_->GetNodeName(), "baseB:  %ld", ahInfo.baseB);
    OP_LOGD(context_->GetNodeName(), "baseS:  %ld", ahInfo.baseS);
    OP_LOGD(context_->GetNodeName(), "baseSTail:  %ld", ahInfo.baseSTail);
    OP_LOGD(context_->GetNodeName(), "baseHTail:  %ld", ahInfo.baseHTail);
    OP_LOGD(context_->GetNodeName(), "baseBTail:  %ld", ahInfo.baseBTail);
    OP_LOGD(context_->GetNodeName(), "baseSCnt:  %ld", ahInfo.baseSCnt);
    OP_LOGD(context_->GetNodeName(), "baseHCnt:  %ld", ahInfo.baseHCnt);
    OP_LOGD(context_->GetNodeName(), "baseBCnt:  %ld", ahInfo.baseBCnt);
    OP_LOGD(context_->GetNodeName(), "tilingKey:  %ld", ahInfo.tilingKey);
    OP_LOGD(context_->GetNodeName(), "ifMask:  %ld", ahInfo.ifMask);
    OP_LOGD(context_->GetNodeName(), "blockDim_:  %ld", ahInfo.blockDim);
}

ge::graphStatus AHInfoParser::ParseAndCheck(AHTilingInfo &ahInfo)
{
    if (ge::GRAPH_SUCCESS != GetOpName() || ge::GRAPH_SUCCESS != GetNpuInfo()) {
        return ge::GRAPH_FAILED;
    }

    if (ge::GRAPH_SUCCESS != CheckInputValid() || ge::GRAPH_SUCCESS != CheckWeightValid() ||
        ge::GRAPH_SUCCESS != CheckMaskValid() || CheckOutputValid()) {
        return ge::GRAPH_FAILED;
    }

    if (ge::GRAPH_SUCCESS != GetTilingKey() || ge::GRAPH_SUCCESS != CoreSplit()) {
        return ge::GRAPH_FAILED;
    }

    GenerateInfo(ahInfo);
    DumpTilingInfo(ahInfo);

    return ge::GRAPH_SUCCESS;
}

// --------------------------TilingPrepare函数定义-------------------------------------
static ge::graphStatus TilingPrepareForAiInfraAggregateHidden(gert::TilingParseContext * /* context */)
{
    return ge::GRAPH_SUCCESS;
}

// --------------------------AiInfraAggregateHiddenTiling类成员函数定义-----------------------
ge::graphStatus AiInfraAggregateHiddenTiling::DoTiling(AHTilingInfo *tilingInfo)
{
    // -------------set blockdim-----------------
    context_->SetBlockDim(static_cast<uint32_t>(tilingInfo->blockDim));
    // -------------set workspacesize-----------------
    size_t *workSpaces = context_->GetWorkspaceSizes(1);
    if (workSpaces == nullptr) {
        return ge::GRAPH_FAILED;
    }
    workSpaces[0] = DEFAULT_WORKSPACE_SIZE;

    // -------------set tilingdata-----------------
    tilingData_.set_ifMask(tilingInfo->ifMask);
    tilingData_.set_sSize(tilingInfo->sSize);
    tilingData_.set_bSize(tilingInfo->bSize);
    tilingData_.set_hSize(tilingInfo->hSize);
    tilingData_.set_baseS(tilingInfo->baseS);
    tilingData_.set_baseB(tilingInfo->baseB);
    tilingData_.set_baseH(tilingInfo->baseH);
    tilingData_.set_baseSTail(tilingInfo->baseSTail);
    tilingData_.set_baseBTail(tilingInfo->baseBTail);
    tilingData_.set_baseHTail(tilingInfo->baseHTail);
    tilingData_.set_baseSCnt(tilingInfo->baseSCnt);
    tilingData_.set_baseBCnt(tilingInfo->baseBCnt);
    tilingData_.set_baseHCnt(tilingInfo->baseHCnt);

    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());

    // -------------set tilingkey-----------------
    // 根据输入数据类型的不同区分tiling key
    context_->SetTilingKey(tilingInfo->tilingKey);

    return ge::GRAPH_SUCCESS;
}

// --------------------------Tiling函数定义---------------------------
ge::graphStatus TilingForAiInfraAggregateHidden(gert::TilingContext *context)
{
    OP_CHECK_IF(context == nullptr,
        OPS_REPORT_VECTOR_INNER_ERR("AiInfraAggregateHidden", "Tiling context is null."),
        return ge::GRAPH_FAILED);
    AHTilingInfo ahInfo;
    AHInfoParser ahInfoParser(context);
    if (ahInfoParser.ParseAndCheck(ahInfo) != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }
    AiInfraAggregateHiddenTiling ahTiling(context);
    return ahTiling.DoTiling(&ahInfo);
}

// --------------------------Tiling函数及TilingPrepare函数注册--------
IMPL_OP_OPTILING(AiInfraAggregateHidden)
    .Tiling(TilingForAiInfraAggregateHidden)
    .TilingParse<AiInfraAggregateHiddenCompileInfo>(TilingPrepareForAiInfraAggregateHidden);

}  // namespace optiling

